// Retrouve le nodeId de la valeur qui vient de changer, et extrait la
// vraie valeur numerique (le palette OPC UA peut renvoyer soit un nombre
// brut, soit un objet imbrique type DataValue: { value: { value: X, dataType: Y }, statusCode, ... }).
//
// IMPORTANT: le format du payload DOIT matcher exactement ce que le backend
// FastAPI attend (voir backend/app/domains/telemetry/subscriber.py) :
// le champ "tag_id" est utilise comme cle principale pour indexer les
// donnees live et l'historique. Sans lui, les donnees arrivent sur le bon
// topic MQTT mais restent invisibles cote frontend/API.

var registry = global.get('tagRegistry') || {};

function extractValue(payload) {
    if (payload === null || payload === undefined) return null;
    if (typeof payload === 'number' || typeof payload === 'boolean' || typeof payload === 'string') {
        return payload;
    }
    if (typeof payload === 'object') {
        var v = payload.value;
        if (v && typeof v === 'object' && 'value' in v) {
            return v.value; // DataValue -> Variant -> value
        }
        if (v !== undefined) return v; // Variant direct
    }
    return payload;
}

function buildOut(nodeId, rawValue, quality) {
    var info = registry[nodeId];
    if (!info) return null;
    var out = {};
    out.topic = info.mqtt_topic;
    out.payload = JSON.stringify({
        tag_id: info.tag_id,
        value: extractValue(rawValue),
        unit: info.unit,
        timestamp: new Date().toISOString(),
        quality: quality || "Good",
        domain: info.domain,
        source: "nodered_opcua"
    });
    out.qos = 0;
    out.retain = false;
    return out;
}

var results = [];

if (Array.isArray(msg.payload)) {
    msg.payload.forEach(function(item) {
        var nodeId = item.nodeId || item.name;
        var out = buildOut(nodeId, item.value !== undefined ? item.value : item, item.statusCode && item.statusCode.name);
        if (out) results.push(out);
    });
} else if (msg.topic && registry[msg.topic]) {
    var out = buildOut(msg.topic, msg.payload, msg.status);
    if (out) results.push(out);
}

if (results.length === 0) {
    node.warn("Tag non reconnu - verifier CHANNEL_DEVICE dans 'Build Tag List' et regarder le debug 'Raw OPC UA output'");
    return null;
}

return [results];
